WHERE kit_esquemas.proyecto_id = (SELECT id FROM kit_proyectos WHERE kit_proyectos.kit_id = v.kit_id AND kit_proyectos.slug = v.slug)
  AND kit_esquemas.tipo = 'svg';

-- 2. Permitir tipo='practica' en kit_proyectos
ALTER TABLE kit_proyectos DROP CONSTRAINT IF EXISTS kit_proyectos_tipo_check;
ALTER TABLE kit_proyectos ADD CONSTRAINT kit_proyectos_tipo_check CHECK (tipo IN ('principal','adicional','practica'));

-- 3. KIT_PROYECTOS (12 practicas previas)
INSERT INTO kit_proyectos (kit_id, titulo, slug, tipo, descripcion, objetivos, orden) VALUES
  ('kit-lv-octavo-egb', 'Enciende tu primer LED', 'practica-primer-led', 'practica', 'Antes de armar el semáforo completo, practica con una sola pieza: hacer que un LED parpadee.', ARRAY['Usar pinMode() y digitalWrite() para controlar una salida digital.', 'Entender por qué un LED necesita una resistencia en serie.'], -2),
  ('kit-lv-octavo-egb', 'Lee un pulsador', 'practica-pulsador', 'practica', 'Practica con el pulsador solo: enciende el LED mientras lo mantienes presionado.', ARRAY['Leer una entrada digital con digitalRead().', 'Usar INPUT_PULLUP para no necesitar una resistencia externa en el pulsador.'], -1),
  ('kit-lv-noveno-egb', 'Mide distancia con el sensor ultrasónico', 'practica-sensor-distancia', 'practica', 'Antes del basurero inteligente, practica con el sensor solo: mide la distancia y míralo en el Monitor Serial.', ARRAY['Entender como un sensor ultrasonico mide distancia con un pulso de sonido.', 'Usar el Monitor Serial para ver datos en tiempo real.'], -2),
  ('kit-lv-noveno-egb', 'Mueve el servomotor', 'practica-servomotor', 'practica', 'Practica con el servomotor solo: hazlo girar de un lado a otro antes de usarlo como tapa del basurero.', ARRAY['Controlar la posicion de un servomotor con la libreria Servo.', 'Entender el rango de movimiento de 0 a 180 grados.'], -1),
  ('kit-lv-decimo-egb', 'Lee la humedad del suelo', 'practica-humedad-suelo', 'practica', 'Antes del sistema de riego, practica con el sensor de humedad solo: mira sus valores en el Monitor Serial.', ARRAY['Leer un sensor analogico con analogRead().', 'Relacionar el valor numerico con tierra humeda o seca.'], -2),
  ('kit-lv-decimo-egb', 'Enciende la bomba con el relé', 'practica-rele', 'practica', 'Practica con el relé solo: enciéndelo y apágalo cada segundo antes de conectarlo al sensor.', ARRAY['Entender que un rele es un interruptor controlado por una señal digital.', 'Controlar un actuador de mayor corriente de forma segura.'], -1),
  ('kit-lv-primero-bach', 'Lee temperatura y humedad', 'practica-dht11', 'practica', 'Antes de la estación meteorológica completa, practica con el sensor DHT11 solo.', ARRAY['Usar una libreria externa (DHT sensor library) por primera vez.', 'Leer dos datos distintos (temperatura y humedad) del mismo sensor.'], -2),
  ('kit-lv-primero-bach', 'Lee el sensor de luz', 'practica-ldr', 'practica', 'Practica con el LDR solo: mira cómo cambia el valor al tapar el sensor con la mano.', ARRAY['Leer un sensor analogico en un microcontrolador de 3.3V (rango 0-4095).', 'Relacionar el valor con mas luz o menos luz.'], -1),
  ('kit-lv-segundo-bach', 'Detecta movimiento', 'practica-pir', 'practica', 'Antes de automatizar la luz, practica con el sensor PIR solo: mira cuándo detecta movimiento.', ARRAY['Leer una señal digital de un sensor de movimiento (PIR).', 'Entender que el PIR necesita unos segundos para calibrarse al encender.'], -2),
  ('kit-lv-segundo-bach', 'Prueba el relé', 'practica-rele-domotica', 'practica', 'Practica con el relé solo: enciéndelo y apágalo antes de conectarlo al sensor de movimiento.', ARRAY['Controlar un rele con optoacoplador desde un ESP32.', 'Entender que el ESP32 solo activa la bobina del rele, nunca toca 110V directamente.'], -1),
  ('kit-lv-tercero-bach', 'Muestra texto en la pantalla LCD', 'practica-lcd', 'practica', 'Antes del sistema completo, practica con la pantalla LCD sola: escribe un mensaje fijo.', ARRAY['Inicializar una pantalla LCD por el protocolo I2C.', 'Escribir texto en una posicion especifica de la pantalla.'], -2),
  ('kit-lv-tercero-bach', 'Mide la distancia', 'practica-distancia', 'practica', 'Practica con el sensor ultrasónico solo antes de combinarlo con el resto del sistema.', ARRAY['Medir distancia con un sensor ultrasonico tolerante a 3.3-5V.', 'Mostrar el resultado por el Monitor Serial.'], -1)
ON CONFLICT (kit_id, slug) DO UPDATE SET
  titulo = EXCLUDED.titulo, descripcion = EXCLUDED.descripcion, objetivos = EXCLUDED.objetivos, orden = EXCLUDED.orden;

-- 4. KIT_CONEXIONES (practicas)
INSERT INTO kit_conexiones (proyecto_id, componente, pin_componente, pin_placa, nota, orden) VALUES
  ((SELECT id FROM kit_proyectos WHERE kit_id = 'kit-lv-octavo-egb' AND slug = 'practica-primer-led'), 'LED ROJO', 'Anodo (+)', 'D8', 'mismo pin que el principal', 1),
  ((SELECT id FROM kit_proyectos WHERE kit_id = 'kit-lv-octavo-egb' AND slug = 'practica-pulsador'), 'PULSADOR PEATON', 'Pin 1', 'D2', 'INPUT_PULLUP, mismo pin que el principal', 1),
  ((SELECT id FROM kit_proyectos WHERE kit_id = 'kit-lv-octavo-egb' AND slug = 'practica-pulsador'), 'LED ROJO', 'Anodo (+)', 'D8', 'mismo pin que el principal', 2),
